import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

def check_condition(k):
    if k <= 0:
        return False

    N = 2 * (k**3)
    tau_N = tau(N)
    target_2k = 2 * k

    is_solution = tau_N == target_2k

    # If it is a solution, perform full factorization check
    if is_solution:
        factors = prime_factorization(N)
        return True, factors
    return False, None

# Test up to k=1000
solutions = []
for k in range(1, 1001):
    is_sol, factors = check_condition(k)
    if is_sol:
        solutions.append((k, factors))

print("Solutions found up to k=1000:")
for k, factors in solutions:
    print(f"k={k}, Factorization of 2k^3: {factors}")

